<script setup>
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {onBeforeRouteLeave} from 'vue-router'
import {api} from '../lib/api'
import {useArcade} from '../stores/arcade'
import {detectiveLevels,detectiveColors} from '../data/detective'
import DetectiveScene from '../components/detective/DetectiveScene.vue'
import PixelMonster from '../components/detective/PixelMonster.vue'
const reduced=ref(window.matchMedia('(prefers-reduced-motion: reduce)').matches);
const s=useArcade(),game=ref(null),busy=ref(false),error=ref(''),phase=ref('title'),event=ref(''),draft=ref(''),feedback=ref(null),current=ref(null),questionDialog=ref(null),exitDialog=ref(null),archiveDialog=ref(null),archive=ref(null),intro=ref(''),previewLevel=ref(1),archiveBusy=ref(false);const revealedHints = ref({});
let eventTimer,exitResolve,leaving=false,alive=true,requestKey='';
const info=computed(()=>detectiveLevels[(game.value?.level??previewLevel.value)-1]),c=computed(()=>game.value?.case),candidates=computed(()=>c.value?.fixture.suspects.filter(x=>c.value.candidates.includes(x.id))??[]),isActive=computed(()=>game.value&&!game.value.done),culprit=computed(()=>c.value?.captured?c.value.candidates[0]:null)
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{return await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
function effect(value){clearTimeout(eventTimer);event.value=value;eventTimer=setTimeout(()=>event.value='',1500)}
async function start(){await run(async()=>{const g=await api('/detective/start',{method:'POST',body:{requestKey:crypto.randomUUID()}});if(!alive)return;game.value=g;previewLevel.value=1;phase.value='opening';intro.value=g.case.dialog})}
function investigate(){phase.value='investigate';intro.value='목격 기록을 확인하고 SQL 수사를 시작해요. 기본 모드는 제한 시간이 없어요.'}
function inspect(id){if(phase.value==='opening'||phase.value==='victory')return;const npc=c.value.fixture.suspects.find(x=>x.id===id);intro.value=npc?`${npc.name}: “제 진술은 테이블에 남겼어요. 추측보다 기록을 확인해 주세요!”`:'노리: “SELECT로 필요한 열을 고르고, WHERE로 조건을 좁히세요. 기록의 suspect_id는 친구의 id와 연결돼요.”'}
function openQuestion(){if(busy.value||!c.value?.question||phase.value!=='investigate'||game.value.paused)return;if(current.value?.id!==c.value.question.id){current.value=c.value.question;draft.value='';feedback.value=null;requestKey=crypto.randomUUID()}questionDialog.value.showModal()}
const currentHint = computed(()=>revealedHints.value[current.value?.id] || current.value?.hint || '');
async function revealHint() {
  if (!current.value || currentHint.value || feedback.value?.correct) return;
  await run(async()=>{
    const {hint} = await api('/detective/'+game.value.id+'/hint',{method:'POST',body:{questionId:current.value.id}});
    revealedHints.value[current.value.id] = hint;
  });
}
async function submit(){if(!draft.value.trim()||feedback.value?.correct)return;await run(async()=>{const r=await api('/detective/'+game.value.id+'/answer',{method:'POST',body:{answer:draft.value,questionId:current.value.id,requestKey}});game.value=r.session;feedback.value=r;effect(r.correct?'clue':'wrong');if(!r.correct){revealedHints.value[current.value.id]=r.hint;requestKey=crypto.randomUUID()}})}
function continueCase(){questionDialog.value.close();feedback.value=null;current.value=null;intro.value=c.value.solved===4?'증거가 모두 모였어요. 수첩의 최종 결과를 보고 범인을 직접 선택하세요!':'단서를 수첩에 기록했어요. 다음 조회로 사건과 연결해 보세요.'}
async function accuse(id){await run(async()=>{const r=await api('/detective/'+game.value.id+'/accuse',{method:'POST',body:{answer:String(id),requestKey:crypto.randomUUID()}});game.value=r.session;if(r.correct){phase.value='victory';effect('clue');intro.value=r.reward?`범인 검거! +${r.reward}P를 받았어요.`:'범인 검거! 이미 최초 보상을 받은 라운드이므로 추가 포인트는 없어요.';await s.refresh();window.dispatchEvent(new Event('spokemon-points-refresh'))}else{effect('wrong');intro.value=r.hint}})}
async function enter(level){if(!game.value)return;await run(async()=>{const g=await api('/detective/'+game.value.id+'/enter',{method:'POST',body:{level}});game.value=g;phase.value=g.case.captured?'victory':'opening';intro.value=g.case.dialog;previewLevel.value=level})}
async function pause(){await run(async()=>{game.value=await api('/detective/'+game.value.id+'/pause',{method:'POST',body:{paused:!game.value.paused}})})}
async function showArchive(){archiveDialog.value.showModal();archiveBusy.value=true;try{archive.value=await api('/detective/history')}catch(e){error.value=e.message}finally{archiveBusy.value=false}}
function confirmLeave(){return new Promise(resolve=>{exitResolve=resolve;exitDialog.value.showModal()})}
function resolveLeave(value){exitDialog.value.close();exitResolve?.(value);exitResolve=null}
async function end(){if(busy.value)return;if(!await confirmLeave())return;await run(async()=>{await api('/detective/'+game.value.id+'/end',{method:'POST',body:{}});game.value=null;phase.value='title';previewLevel.value=1})}
async function leaveRoute(){if(busy.value){error.value='진행 중인 요청이 끝난 뒤 이동해 주세요.';return false}if(!isActive.value)return true;if(!await confirmLeave())return false;try{await api('/detective/'+game.value.id+'/end',{method:'POST',body:{}});leaving=true;return true}catch(e){error.value=e.message;return false}}
onBeforeRouteLeave(leaveRoute)
function beforeUnload(e){if(isActive.value){e.preventDefault();e.returnValue=''}}
function pagehide(){if(game.value&&!leaving)fetch('/api/detective/'+game.value.id+'/end',{method:'POST',headers:{'Content-Type':'application/json','X-Spokemon-Request':'1'},body:'{}',credentials:'same-origin',keepalive:true}).catch(()=>{})}
onMounted(()=>{window.addEventListener('beforeunload',beforeUnload);window.addEventListener('pagehide',pagehide);run(()=>api('/detective/reset',{method:'POST',body:{}}))})
onUnmounted(()=>{alive=false;clearTimeout(eventTimer);window.removeEventListener('beforeunload',beforeUnload);window.removeEventListener('pagehide',pagehide);exitResolve?.(false);for(const d of[questionDialog,exitDialog,archiveDialog])d.value?.close()})
</script>
<template><div :class="['sql-game',{'reduced-effects':reduced,'is-paused':game?.paused}]"><header class="sql-game-header"><div><p>PIXEL MYSTERY RPG <b>NEW!</b></p><h1>SQL 미스터리 탐정단</h1><span>LEVEL {{game?.level??1}} · {{info.concept}}</span></div><div class="sql-game-actions"><label class="sql-motion-toggle"><input v-model="reduced" type="checkbox"/>연출 줄이기</label><button :disabled="busy" @click="showArchive">탐정 기록</button><button v-if="game&&!game.done" :disabled="busy" @click="pause">{{game.paused?'수사 재개':'일시정지'}}</button><button v-if="game" :disabled="busy" @click="end">게임 종료</button><RouterLink v-else to="/home" class="button">메인으로</RouterLink></div></header><p v-if="error" class="sql-error" role="alert">{{error}}</p>
<template v-if="!game"><section class="sql-title"><DetectiveScene :level="5" phase="title" :solved="0"/><div class="sql-title-copy"><small>THE CASE OF THE MISSING CLUE</small><h2>작은 단서가<br/>커다란 진실이 되는 밤</h2><p>귀여운 몬스터 탐정과 함께 SQL로 증거를 찾아요.<br/>다섯 사건을 해결하고 SQL MASTER가 되어 보세요!</p><strong>5 LEVEL · 최초 클리어 최대 200P</strong><button :disabled="busy" @click="start">{{busy?'사건 준비 중…':'수사 시작 →'}}</button></div></section><div class="sql-level-browser"><button aria-label="이전 사건" :disabled="previewLevel===1" @click="previewLevel--">〈</button><article><small>LEVEL {{previewLevel}}{{previewLevel===5?' MASTER':''}}</small><h3>{{info.name}}</h3><p>{{info.concept}}</p><b>{{info.reward}}P</b><span v-if="previewLevel>1"> 🔒 이전 라운드 클리어 후 해금</span></article><button aria-label="다음 사건" :disabled="previewLevel===5" @click="previewLevel++">〉</button></div><details class="sql-how"><summary>게임 방법</summary><ol><li>목격자와 대화하고 사건 테이블을 읽어요.</li><li>LEVEL 1~4는 5지선다 또는 빈칸, LEVEL 5는 SELECT 조회문을 직접 작성해요.</li><li>정답이면 조회 결과와 연결 해설이 탐정 수첩에 쌓여요. 오답에는 힌트를 주며 제한 시간은 없어요.</li><li>필수 미션 4개를 해결한 뒤 범인을 선택해야 다음 사건이 열려요.</li><li>재입장 시 LEVEL 1로 초기화돼요. 포인트·풀이 기록·배지는 보존되며 보상은 사용자별 각 라운드 최초 1회예요.</li></ol></details></template>
<template v-else><nav class="sql-rounds" aria-label="사건 단계"><button v-for="l in detectiveLevels" :key="l.id" :aria-pressed="game.level===l.id" :disabled="busy" @click="enter(l.id)">{{l.id>game.unlocked?'🔒':game.cleared.includes(l.id)?'✓':''}} L{{l.id}} · {{l.reward}}P</button></nav><div class="sql-status"><span>사건 단서 <b>{{c.solved}} / 4</b></span><span>검거 <b>{{game.cleared.length}} / 5</b></span><span>이번 수사 <b>{{game.earned}}P</b></span></div><div class="sql-play-layout"><section class="sql-main"><h2>{{c.title}}</h2><DetectiveScene :level="game.level" :solved="c.solved" :phase="phase" :event="event" :suspects="c.fixture.suspects.filter(x=>c.candidates.includes(x.id))" :culprit="culprit" @inspect="inspect"/><div v-if="game.paused" class="sql-paused" role="status">수사가 일시정지되었어요. 재개 버튼을 눌러 주세요.</div><div class="sql-dialogue" role="status"><b>목격자 노리 / 탐정 새싹</b><p>{{intro}}</p><button v-if="phase==='opening'" :disabled="busy||game.paused" @click="investigate">현장 도착 · 수사 시작</button><button v-else-if="phase==='investigate'&&c.question" :disabled="busy||game.paused" @click="openQuestion">SQL 수사 · 미션 {{c.solved+1}} 풀기</button><template v-else-if="phase==='victory'"><strong v-if="game.done" class="sql-master-badge">✦ SQL MASTER · 수료 배지 획득!</strong><button v-if="!game.done" :disabled="busy" @click="enter(game.level+1)">다음 사건으로 →</button><button v-else :disabled="busy" @click="end">수사 마치기</button></template></div><section class="sql-evidence-tables"><details open><summary>사건 데이터 · 테이블과 연결 키</summary><p>suspects.id ↔ sightings.suspect_id ↔ evidence.suspect_id · SQL은 SQLite SELECT 문법으로 실행돼요.</p><div v-for="(rows,table) in c.fixture" :key="table" class="sql-table-wrap"><h3>{{table}}</h3><table><thead><tr><th v-for="key in Object.keys(rows[0])" :key="key">{{key}}</th></tr></thead><tbody><tr v-for="(row,n) in rows" :key="n"><td v-for="(v,key) in row" :key="key">{{v}}</td></tr></tbody></table></div></details></section></section><aside class="sql-notebook"><h2>탐정 수첩</h2><p>{{info.concept}}</p><label>{{game.level===5?'범인 도주 게이지':'추격 · 증거 확보'}}<progress :value="game.level===5?100-c.solved*25:c.solved*25" max="100"/></label><p>{{game.level===5?'정답으로 도주 게이지를 낮추세요.':'정답을 맞힐수록 탐정이 가까워져요.'}} 시간제한 없음</p><h3>용의자 {{candidates.length}} / 5</h3><div class="sql-suspect-list"><button v-for="suspect in c.fixture.suspects" :key="suspect.id" :class="{excluded:!c.candidates.includes(suspect.id)}" :disabled="busy||game.paused||c.solved!==4||c.captured" @click="accuse(suspect.id)"><PixelMonster :color="detectiveColors[suspect.id-1]" :emotion="event==='wrong'?'panic':c.captured&&suspect.id===culprit?'joy':'idle'" :label="suspect.name"/><span>{{suspect.name}}<small>#{{suspect.id}} {{c.solved===4&&!c.captured?'범인으로 지목':c.candidates.includes(suspect.id)?'수사 중':'후보 제외'}}</small></span></button></div><p v-if="c.solved===4&&!c.captured" class="sql-accuse-tip">모든 단서를 모았어요. 마지막 조회 결과의 id와 비교해 범인을 선택하세요!</p><h3>확보한 단서 {{c.clues.length}}</h3><p v-if="!c.clues.length">SQL 미션을 해결하면 단서가 기록돼요.</p><details v-for="(clue,i) in c.clues" :key="i" class="sql-clue"><summary>✦ {{clue.title}} · 조회 결과</summary><pre>{{clue.sql}}</pre><div class="sql-table-wrap"><table><thead><tr><th v-for="col in clue.columns" :key="col">{{col}}</th></tr></thead><tbody><tr v-for="(row,k) in clue.rows" :key="k"><td v-for="(v,j) in row" :key="j">{{v}}</td></tr></tbody></table></div><p>{{clue.explanation}}</p></details></aside></div></template>
<dialog ref="questionDialog" class="sql-modal" aria-label="SQL 수사 문제" @cancel.prevent="questionDialog.close()"><header><h2>미션 {{(current?.index??c?.solved??0)+1}} · {{game?.level===5?'MASTER SQL':'단서 조회'}}</h2><button :disabled="busy" aria-label="문제 닫기" @click="questionDialog.close()">✕</button></header><template v-if="current"><p>{{current.prompt}}</p>
<button v-if="!feedback?.correct" type="button" :disabled="busy || !!currentHint" @click="revealHint">{{currentHint?'힌트 사용 완료':'힌트 보기 · 1회'}}</button>
<p v-if="currentHint && !feedback?.correct" role="status">힌트 · {{currentHint}}</p><p class="sql-schema-tip">아래 사건 테이블을 펼쳐 보면서 작성하세요. 정답과 증거의 관계를 확인해 보세요.</p><details class="sql-modal-tables"><summary>사건 테이블 펼치기 · suspects / sightings / evidence</summary><p>suspects.id = sightings.suspect_id = evidence.suspect_id</p><div v-for="(rows,table) in c.fixture" :key="table" class="sql-table-wrap"><h3>{{table}}</h3><table><thead><tr><th v-for="key in Object.keys(rows[0])" :key="key">{{key}}</th></tr></thead><tbody><tr v-for="(row,n) in rows" :key="n"><td v-for="(v,key) in row" :key="key">{{v}}</td></tr></tbody></table></div></details><pre v-if="current.template">{{current.template}}</pre><form @submit.prevent="submit"><fieldset :disabled="busy||feedback?.correct"><label v-for="option in current.options" :key="option.id" class="sql-option"><input v-model="draft" type="radio" name="sql-answer" :value="option.id"/><code>{{option.label}}</code></label><label v-if="current.type==='blank'">빈칸에 들어갈 SQL 키워드<input v-model="draft" maxlength="100" autocomplete="off" spellcheck="false" required/></label><label v-if="current.type==='code'">SQL 코드 직접 작성<textarea v-model="draft" rows="8" maxlength="4000" spellcheck="false" autocapitalize="off" autocorrect="off" autocomplete="off" placeholder="SELECT ... FROM ... JOIN ... ON ... WHERE ..." required/><small>읽기 전용 · 최대 4,000자 · 서버 격리 실행</small></label></fieldset><button v-if="!feedback?.correct" :disabled="busy||!draft.trim()">{{busy?'SQL 기록 확인 중…':'SQL 제출 · 증거 확인'}}</button></form><div v-if="feedback" :class="['sql-feedback',{correct:feedback.correct}]" role="status"><template v-if="feedback.correct"><PixelMonster class="sql-feedback-monster" color="#80c5a2" role="detective" emotion="joy" label="기뻐하는 탐정"/><h3 class="sql-clue-found">✦ 단서를 발견했어요!</h3><div class="sql-table-wrap"><table><thead><tr><th v-for="col in feedback.columns" :key="col">{{col}}</th></tr></thead><tbody><tr v-for="(row,i) in feedback.rows" :key="i"><td v-for="(v,j) in row" :key="j">{{v}}</td></tr></tbody></table></div><pre>{{feedback.explanation}}</pre><button @click="continueCase">수첩 기록 · 수사 계속 →</button></template><template v-else><PixelMonster class="sql-feedback-monster" color="#80c5a2" role="detective" emotion="think" label="고민하는 탐정"/><h3>탐정이 생각 중이에요…</h3><p>{{feedback.execution}}</p><p>답을 수정한 뒤 다시 제출해 보세요.</p></template></div><p v-if="error" role="alert">{{error}}</p></template></dialog>
<dialog ref="exitDialog" class="sql-modal" aria-label="탐정 게임 종료 확인" @cancel.prevent="resolveLeave(false)"><h2>수사를 종료할까요?</h2><p>게임을 종료하면 진행 상황이 초기화됩니다. 종료하시겠습니까?</p><p>획득 포인트·학습 기록·SQL MASTER 배지는 유지돼요.</p><div class="sql-game-actions"><button @click="resolveLeave(false)">계속 수사</button><button @click="resolveLeave(true)">게임 종료</button></div></dialog>
<dialog ref="archiveDialog" class="sql-modal" aria-label="탐정 학습 기록"><header><h2>탐정 학습 기록</h2><button aria-label="기록 닫기" @click="archiveDialog.close()">✕</button></header><p v-if="archiveBusy">기록을 불러오는 중…</p><template v-else-if="archive"><p>최초 클리어 보상 {{archive.total}} / 200P <b v-if="archive.badge" class="sql-master-badge">✦ SQL MASTER</b></p><p>최근 100개 풀이 · 오답에는 힌트만 표시돼요.</p><details v-for="(a,i) in archive.attempts" :key="i"><summary>LEVEL {{a.level}} · {{a.kind==='accuse'?'범인 지목':'SQL 미션'}} · {{a.correct?'정답':'복습 필요'}}</summary><p>{{a.feedback.prompt}}</p><p>내 답안</p><pre>{{a.feedback.answerLabel||a.answer}}</pre><pre>{{a.feedback.explanation||a.feedback.hint}}</pre></details><p v-if="!archive.attempts.length">첫 사건을 해결하고 기록을 남겨 보세요!</p></template><p v-if="error" role="alert">{{error}}</p></dialog>
</div></template>
<style src="../detective.css"></style>
